"""R49 artifact integrity only; semantic answers require source-based inspection."""
import json
import re
from urllib.parse import unquote
from v2_scoped_knowledge import OUT, FILES, UPDATE

checks={}
for stage,case in [('r49','knowledge_scope'),('r49update','knowledge_update')]:
    for arm in ['A','G','V2']:
        root=OUT/'runs'/stage/case/arm
        if not (root/'run.json').exists():continue
        workspace=root/'workspace'
        expected={name:(OUT/'fixtures'/name).read_bytes() for name in FILES}
        if stage=='r49update':expected['07-正式补充D.md']=(OUT/'evaluator-update.md').read_bytes()
        inputs={name:(workspace/'inputs'/name).read_bytes()==content for name,content in expected.items()}
        links=[]
        documents=[]
        for doc in workspace.rglob('*.md'):
            rel=doc.relative_to(workspace)
            if '.agents' in rel.parts or 'inputs' in rel.parts:continue
            documents.append(str(rel))
            for href in re.findall(r'\[[^\]]*\]\(([^)]+)\)',doc.read_text(encoding='utf-8-sig')):
                href=unquote(href.strip('<>').split('#')[0])
                if not href or '://' in href:continue
                links.append({'document':str(rel),'target':href,'exists':(doc.parent/href).exists(),
                              'archivedCopy':rel.parts[0].startswith('备份-')})
        checks[stage+'/'+arm]={'inputs':inputs,'localLinks':links,'documents':documents,
            'pass':all(inputs.values()) and all(x['exists'] for x in links),
            'currentDocumentLinksPass':all(x['exists'] for x in links if not x['archivedCopy']),
            'limits':'File existence and input bytes only. Does not prove anchor correctness, answer validity, usability or automatic maintenance.'}
(OUT/'integrity-independent.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2),encoding='utf-8')
for condition,check in checks.items():print(condition,check['pass'],len(check['localLinks']),'local links')
assert checks and all(check['pass'] for check in checks.values())

